(()=>{"use strict";const e="ho_data_consent_v1";document.addEventListener("DOMContentLoaded",()=>{!async function(){const t=await async function(){const e=await chrome.storage.local.get("devMode");return!0===e.devMode?"http://localhost:3000":(e.devMode,"https://hireoven.com")}();document.getElementById("privacy-link").href=`${t}/privacy#extension`,document.getElementById("agree-btn").addEventListener("click",()=>{(async function(){await chrome.storage.local.set({[e]:!0})})().then(()=>{window.location.href=`${t}/dashboard`})}),document.getElementById("decline-btn").addEventListener("click",()=>{document.getElementById("declined-note").classList.add("visible")})}()})})();